/// `iam.billing`: trusted metering, checks, reports and the scheduler jobs.
pub struct BillingRuntime {
    ctx: Arc<ServerContext>,
}

/// `createBillingRuntime(...)`. Construction never fails in the skeleton; validation the TypeScript factory does on
/// construction belongs here when the module is ported.
pub fn create_billing_runtime(ctx: &Arc<ServerContext>) -> IamResult<BillingRuntime> {
    Ok(BillingRuntime { ctx: ctx.clone() })
}

