    pub fn settings(&self) -> IamResult<Value> {
        Err(not_ported("api/billing.ts BillingRuntime.settings"))
    }
    /// Records usage without a credential and without an audit event (the hot path for metering).
    pub async fn record(&self, input: &Value) -> IamResult<crate::billing::UsageReceipt> {
        Err(not_ported("api/billing.ts BillingRuntime.record"))
    }
